import { useEffect, useState } from "react";
import type { Home } from "./api.ts";
import { getHomes } from "./api.ts";
import { HomeList } from "./components/HomeList.tsx";
import { IncidentList } from "./components/IncidentList.tsx";

export function App() {
  const [homes, setHomes] = useState<Home[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  useEffect(() => {
    getHomes().then(setHomes, (reason: unknown) => setError(String(reason)));
  }, []);

  const selected = homes?.find((home) => home.id === selectedId) ?? null;

  return (
    <div className="app">
      <header>
        <h1>Property monitor</h1>
      </header>

      {error && <p className="error">Could not load homes: {error}</p>}
      {!homes && !error && <p className="muted">Loading…</p>}

      {homes && (
        <main>
          <HomeList homes={homes} selectedId={selectedId} onSelect={setSelectedId} />
          {selected ? (
            <IncidentList home={selected} />
          ) : (
            <section className="panel">
              <p className="muted">Pick a home to see its incidents.</p>
            </section>
          )}
        </main>
      )}
    </div>
  );
}

/** Everything this app knows about the backend. */

const BASE = import.meta.env.VITE_API_URL ?? "http://localhost:3001";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
  openIncidents: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

async function get<T>(path: string): Promise<T> {
  const res = await fetch(`${BASE}${path}`);
  if (!res.ok) throw new Error(`${path} returned ${res.status}`);
  // The response shape is trusted here, not validated. The backend's own tests are what hold it.
  return res.json() as Promise<T>;
}

export async function getHomes(): Promise<Home[]> {
  const body = await get<{ homes: Home[] }>("/api/homes");
  return body.homes;
}

export async function getIncidents(homeId: string, status?: IncidentStatus): Promise<Incident[]> {
  const query = status ? `?status=${status}` : "";
  const body = await get<{ incidents: Incident[] }>(`/api/homes/${homeId}/incidents${query}`);
  return body.incidents;
}

import { useEffect, useState } from "react";
import type { Home, Incident } from "../api.ts";
import { getIncidents } from "../api.ts";
import { formatPeak, formatStarted, kindLabel } from "../format.ts";

export function IncidentList({ home }: { home: Home }) {
  const [incidents, setIncidents] = useState<Incident[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIncidents(null);
    setError(null);
    let current = true;
    getIncidents(home.id, "open").then(
      (rows) => { if (current) setIncidents(rows); },
      (reason: unknown) => { if (current) setError(String(reason)); },
    );
    return () => {
      current = false;
    };
  }, [home.id]);

  return (
    <section className="panel" aria-label={`Incidents for ${home.name}`}>
      <h2>{home.name}</h2>
      <p className="muted">
        {home.devices} device{home.devices === 1 ? "" : "s"} · {home.timezone}
      </p>

      {error && <p className="error">Could not load incidents: {error}</p>}
      {!incidents && !error && <p className="muted">Loading…</p>}
      {incidents?.length === 0 && <p className="muted">No open incidents.</p>}

      {incidents && incidents.length > 0 && (
        <ul className="incidents">
          {incidents.map((incident) => (
            <li key={incident.id} className={`incident ${incident.kind}`}>
              <span className="incident-kind">{kindLabel[incident.kind]}</span>
              <span className="incident-when">{formatStarted(incident.startedAt)}</span>
              <span className="incident-peak">{formatPeak(incident.peakDb)}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

import type { Home } from "../api.ts";

type Props = {
  homes: Home[];
  selectedId: string | null;
  onSelect: (id: string) => void;
};

export function HomeList({ homes, selectedId, onSelect }: Props) {
  return (
    <nav className="panel" aria-label="Homes">
      <h2>Homes</h2>
      <ul className="homes">
        {homes.map((home) => (
          <li key={home.id}>
            <button
              type="button"
              className={home.id === selectedId ? "home selected" : "home"}
              aria-current={home.id === selectedId}
              onClick={() => onSelect(home.id)}
            >
              <span className="home-name">{home.name}</span>
              <span className="home-address">{home.address}</span>
              {home.openIncidents > 0 && (
                <span className="badge" title={`${home.openIncidents} open incidents`}>
                  {home.openIncidents}
                </span>
              )}
            </button>
          </li>
        ))}
      </ul>
    </nav>
  );
}

/** Display helpers. Pure, so they are the easy thing to unit test. */

export function formatStarted(iso: string, now: Date = new Date()): string {
  const started = new Date(iso);
  const minutes = Math.round((now.getTime() - started.getTime()) / 60_000);
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `${hours} h ago`;
  return `${Math.round(hours / 24)} d ago`;
}

export function formatPeak(peakDb: number | null): string {
  return peakDb === null ? "—" : `${peakDb} dB`;
}

export const kindLabel = { noise: "Noise", occupancy: "Occupancy", offline: "Device offline" };

:root {
  --bg: #fbfaf8;
  --panel: #ffffff;
  --ink: #1d1b19;
  --muted: #6d675f;
  --line: #e4e0d9;
  --accent: #1f6f5c;
  --alert: #a8321e;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
}

.app { max-width: 60rem; margin: 0 auto; padding: 2rem 1.25rem 4rem; }
h1 { font-size: 1.4rem; margin: 0 0 1.5rem; letter-spacing: -0.01em; }
h2 { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); margin: 0 0 0.75rem; }

main { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 1.25rem; align-items: start; }
@media (max-width: 48rem) { main { grid-template-columns: 1fr; } }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 0.75rem; padding: 1rem; }
.muted { color: var(--muted); margin: 0; }
.error { color: var(--alert); }

.homes, .incidents { list-style: none; margin: 0; padding: 0; }

.home {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas: "name badge" "address badge";
  gap: 0 0.5rem;
  width: 100%;
  padding: 0.6rem 0.7rem;
  border: 1px solid transparent;
  border-radius: 0.5rem;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.home:hover { background: #f5f2ec; }
.home.selected { border-color: var(--accent); background: #f0f6f3; }
.home-name { grid-area: name; font-weight: 550; }
.home-address { grid-area: address; font-size: 0.85rem; color: var(--muted); }

.badge {
  grid-area: badge;
  align-self: center;
  min-width: 1.5rem;
  padding: 0.1rem 0.4rem;
  border-radius: 999px;
  background: var(--alert);
  color: white;
  font-size: 0.78rem;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.incident {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 0.75rem;
  padding: 0.55rem 0;
  border-top: 1px solid var(--line);
  font-size: 0.92rem;
}
.incident:first-child { border-top: none; }
.incident-when, .incident-peak { color: var(--muted); font-variant-numeric: tabular-nums; }

import { describe, expect, it } from "vitest";
import { formatPeak, formatStarted } from "../src/format.ts";

const now = new Date("2026-11-01T12:00:00Z");

describe("formatStarted", () => {
  it("reads recent times in minutes", () => {
    expect(formatStarted("2026-11-01T11:35:00Z", now)).toBe("25 min ago");
  });

  it("switches to hours after an hour", () => {
    expect(formatStarted("2026-11-01T09:00:00Z", now)).toBe("3 h ago");
  });

  it("switches to days after a day", () => {
    expect(formatStarted("2026-10-29T12:00:00Z", now)).toBe("3 d ago");
  });
});

describe("formatPeak", () => {
  it("shows a dash when there is no reading", () => {
    expect(formatPeak(null)).toBe("—");
  });

  it("shows decibels when there is one", () => {
    expect(formatPeak(86)).toBe("86 dB");
  });
});

