import { describe, expect, it } from "vitest";
import { formatHour, formatPeak, formatStarted, last24HourCells, summarizeHours } from "../src/format.ts";

const now = new Date("2026-11-01T12:00:00Z");

edits.oldText:
describe("formatPeak", () => {
  it("shows a dash when there is no reading", () => {
    expect(formatPeak(null)).toBe("—");
  });

  it("shows decibels when there is one", () => {
    expect(formatPeak(86)).toBe("86 dB");
  });
});

edits.newText:
describe("formatPeak", () => {
  it("shows a dash when there is no reading", () => {
    expect(formatPeak(null)).toBe("—");
  });

  it("shows decibels when there is one", () => {
    expect(formatPeak(86)).toBe("86 dB");
  });
});

describe("last24HourCells", () => {
  it("returns 24 cells, oldest first, ending at the current hour", () => {
    const cells = last24HourCells([], now);
    expect(cells).toHaveLength(24);
    expect(cells[0].start).toEqual(new Date("2026-10-31T13:00:00Z"));
    expect(cells[23].start).toEqual(new Date("2026-11-01T12:00:00Z"));
    expect(cells.every((cell) => cell.severity === "none")).toBe(true);
  });

  it("tags the hour an incident started in", () => {
    const cells = last24HourCells([{ kind: "offline", startedAt: "2026-11-01T09:30:00Z" }], now);
    expect(cells[20].start).toEqual(new Date("2026-11-01T09:00:00Z"));
    expect(cells[20].severity).toBe("offline");
  });

  it("keeps the worst kind when several incidents share an hour", () => {
    const cells = last24HourCells(
      [
        { kind: "offline", startedAt: "2026-11-01T09:10:00Z" },
        { kind: "occupancy", startedAt: "2026-11-01T09:50:00Z" },
        { kind: "noise", startedAt: "2026-11-01T09:59:00Z" },
      ],
      now,
    );
    expect(cells[20].severity).toBe("noise");
  });

  it("ranks occupancy above offline", () => {
    const cells = last24HourCells(
      [
        { kind: "offline", startedAt: "2026-11-01T09:10:00Z" },
        { kind: "occupancy", startedAt: "2026-11-01T09:50:00Z" },
      ],
      now,
    );
    expect(cells[20].severity).toBe("occupancy");
  });

  it("ignores incidents older than 24 hours, in the future, or unparseable", () => {
    const cells = last24HourCells(
      [
        { kind: "noise", startedAt: "2026-10-31T12:59:59Z" },
        { kind: "noise", startedAt: "2026-11-01T12:00:01Z" },
        { kind: "noise", startedAt: "not a date" },
      ],
      now,
    );
    expect(cells.every((cell) => cell.severity === "none")).toBe(true);
  });
});

describe("formatHour", () => {
  it("formats hours in 12-hour local time", () => {
    expect(formatHour(new Date(2026, 10, 1, 14))).toBe("2 PM");
    expect(formatHour(new Date(2026, 10, 1, 9))).toBe("9 AM");
    expect(formatHour(new Date(2026, 10, 1, 0))).toBe("12 AM");
    expect(formatHour(new Date(2026, 10, 1, 12))).toBe("12 PM");
  });
});

describe("summarizeHours", () => {
  it("tallies each severity in words", () => {
    const cells = last24HourCells(
      [
        { kind: "noise", startedAt: "2026-11-01T11:10:00Z" },
        { kind: "noise", startedAt: "2026-11-01T05:10:00Z" },
        { kind: "occupancy", startedAt: "2026-11-01T09:10:00Z" },
        { kind: "offline", startedAt: "2026-11-01T03:10:00Z" },
      ],
      now,
    );
    expect(summarizeHours(cells)).toBe(
      "Last 24 hours: 2 noisy hours, 1 occupancy hour, 1 device-offline hour, 20 quiet hours.",
    );
  });
});

